namespace ChatVox.Queue;
public sealed record SpeechItem(string Text,DateTimeOffset Created);
public sealed class FreshQueue(int max=8,TimeSpan? age=null) { readonly object sync=new(); readonly Queue<SpeechItem> q=new(); int max=max; TimeSpan age=age??TimeSpan.FromSeconds(30); public event Action<int>? Expired; public int Max {get {lock(sync)return max;}set {lock(sync)max=Math.Max(1,value);}} public TimeSpan Age {get {lock(sync)return age;}set {lock(sync)age=value;}} public int Count {get {lock(sync){PurgeCore(DateTimeOffset.UtcNow);return q.Count;}}} public void Add(string text,DateTimeOffset? now=null){lock(sync){var n=now??DateTimeOffset.UtcNow;PurgeCore(n);while(q.Count>=max)q.Dequeue();q.Enqueue(new(text,n));}} public SpeechItem? Take(DateTimeOffset? now=null){lock(sync){PurgeCore(now??DateTimeOffset.UtcNow);return q.TryDequeue(out var item)?item:null;}} public void Clear(){lock(sync)q.Clear();} public void Purge(DateTimeOffset? now=null){lock(sync)PurgeCore(now??DateTimeOffset.UtcNow);} void PurgeCore(DateTimeOffset n){var expired=0;while(q.TryPeek(out var x)&&n-x.Created>age){q.Dequeue();expired++;}if(expired>0)Expired?.Invoke(expired);}}
